def _segments(text,spans):
    out=[]
    for x in spans:
        if isinstance(x,str): out.append(x.casefold())
        elif isinstance(x,dict):
            if "text" in x: out.append(str(x.get("text","")).casefold())
            else:
                a=int(x.get("start",x.get("begin",0))); b=int(x.get("end",x.get("stop",a)))
                out.append(text[a:b].casefold())
        elif isinstance(x,(list,tuple)) and len(x)>=2: out.append(text[int(x[0]):int(x[1])].casefold())
        else: out.append("")
    return out

def _has(s,words):
    return any(w in s for w in words)

def _back(out,xs,i,kind):
    for j in reversed(range(i+1)):
        s=xs[j]
        if kind=="def":
            if _has(s,("confidential information","proprietary information","evaluation material","information”","information\"")) and _has(s,(" means"," shall mean"," shall include")):
                out.add(j); return j
        elif _has(s,("shall not include","does not include","will not include","shall not apply","does not apply","obligations shall not apply","restrictions shall not apply","exclusions from confidential","inoperative as to")):
            out.add(j); return j
    return -1

def propose_members(text,spans,public_hypothesis_key):
    xs=_segments(text,spans); out=set(); k=public_hypothesis_key
    direct={
      "nda-11":("reverse engineer","reverse-engineer","decompile","de-compile","disassemble"),
      "nda-15":("no license","no licence","no rights","does not grant","not construed as granting","granting or conferring any rights","remain the property","remains the property","exclusive property","sole property","retain all rights","no title","no interest","does not acquire","no proprietary interest","not transferred","property of the disclos","owned solely"),
      "nda-10":("existence of this agreement","existence and terms","existence or contents","contents of this agreement","terms of this agreement","fact that discussions","discussions or negotiations","discussions and negotiations","negotiations are taking place","discussions are taking place","transaction information","fact that information has been made available","status of those discussions","existence and content of the discussions","non-disclosure of transaction","confidentiality of business relationship","public announcement concerning"),
      "nda-19":("shall survive","will survive","survive termination","survive expiration","continue to be bound","continue in force","continue to apply","remain binding","after termination","beyond termination","notwithstanding the return","notwithstanding such return","unlimited in time","survive indefinitely","remain in effect indefinitely","termination shall not affect","continue beyond"),
      "nda-18":("solicit for employment","solicit or hire","solicit or employ","solicit nor hire","solicit, entice","solicit, induce","offer employment","offer to hire","employ or retain","employ or engage","contract for the services","initiate contact for employment","encourage any employee"),
      "nda-17":("shall not copy","not copy","nor copy","not reproduce","copy or reproduce","may only make","only make such copies","may make copies","make copies","copies required","copying","duplicate","reduce to writing","reproduce in any form"),
      "nda-4":("solely for","only for","used solely","used only","no purpose other","not use","use only","except for the purpose","sole purpose","for no other purpose","other than the purpose","only in connection with","limited to use for","exclusively for")}
    if k in direct:
        for i,s in enumerate(xs):
            if _has(s,direct[k]):
                out.add(i)
                if k=="nda-10": _back(out,xs,i,"def")
    if k=="nda-2":
        subjects=("business","financial","commercial","marketing","customer","client","supplier","employee","personnel","operational","contractual","sales","pricing","medical","genetic","membership","non-technical")
        for i,s in enumerate(xs):
            if _has(s,subjects) and _has(s,("confidential information","proprietary information","evaluation material","information means","shall include","includes, without","including, without")):
                out.add(i); _back(out,xs,i,"def")
            if "trade secret" in s and "mean" in s:
                out.add(i)
                for j in range(i+1,min(len(xs),i+3)):
                    if _has(xs[j],("software","technology","evaluation material")): out.add(j)
    elif k=="nda-1":
        marks=("marked","mark or label","designated","identified as","identified at","identified orally","identify it in writing","notifying the recipient","reasonable person","reasonably understood","should reasonably","circumstances of disclosure","nature of the information","whether or not marked","need not be marked","does not need to be marked","list of confidential information")
        for i,s in enumerate(xs):
            if _has(s,marks) and _has(s,("confidential","proprietary","information","disclos","list")):
                out.add(i); _back(out,xs,i,"def")
    elif k in ("nda-12","nda-13"):
        words=("independently developed","independent development","developed independently","independently derived","right to independently develop","developing information internally","similar to or compete") if k=="nda-12" else ("from a third party","from third parties","third party having","third party who","another source","independent source","source other than","received from an independent","lawfully obtained","rightfully disclosed","rightfully furnished")
        for i,s in enumerate(xs):
            if _has(s,words):
                out.add(i); h=_back(out,xs,i,"exc")
                if h>=0:
                    d=_back(out,xs,h,"def")
                    if d>=0 and h-d>6: out.discard(d)
    elif k=="nda-3":
        for i,s in enumerate(xs):
            if _has(s,("oral","orally","verbally","uttered","spoken","whatever form","any form whatsoever","tangible or intangible","form or medium","irrespective of the form")) and _has(s,("information","disclos","communicat","confidential","proprietary","evaluation material")):
                out.add(i); h=_back(out,xs,i,"def")
                if h>=0:
                    for j in range(i+1,min(len(xs),i+3)):
                        if _has(xs[j],("written form","electronically","form or medium")) and _has(xs[j],("information","document")): out.add(j)
    elif k=="nda-16":
        acts=("return","destroy","delete","erase","deliver up","deliver back","surrender")
        timing=("termination","expiration","completion","conclusion","assessment period","end of employment","end of the term","not wish to proceed","not consummated","ceasing to be interested","business relationship is not established")
        for i,s in enumerate(xs):
            if _has(s,acts) and _has(s,("information","data","material","document","copies","records","property")):
                for j in range(max(0,i-2),min(len(xs),i+3)):
                    if _has(xs[j],timing): out.update(range(min(i,j),max(i,j)+1))
    elif k=="nda-20":
        retain=("retain one","may retain","entitled to retain","archival copy","archive copy","back-up","backup","not required to erase","not required to delete","infeasible","keep one copy","single copy","not obligated to return or destroy","required to retain")
        for i,s in enumerate(xs):
            if _has(s,retain) or (_has(s,("return","destroy","surrender","deliver back")) and _has(s,("information","data","material","document","copies","records","property"))): out.add(i)
    elif k=="nda-8":
        legal=("required by law","required to disclose","legally compelled","court order","subpoena","legal process","governmental authority","regulatory authority","judicial process","administrative process","operation of law","required by applicable law")
        for i,s in enumerate(xs):
            if _has(s,legal):
                for j in range(max(0,i-3),min(len(xs),i+4)):
                    if _has(xs[j],("notice","notify","consult","inform","advise")): out.update((i,j))
                _back(out,xs,i,"exc")
    elif k in ("nda-7","nda-5"):
        actors=("employee","employees","personnel","staff member","officer","director") if k=="nda-5" else ("agent","consultant","advisor","adviser","counsel","accountant","contractor","subcontractor","representative","third party","professional adviser","affiliate")
        access=("disclose","disclosure","access","furnish","provide","share","supply","made available","need to know","may reveal","restricting access")
        chosen=[]
        for i,s in enumerate(xs):
            if _has(s,actors) and _has(s,access): chosen.append(i); out.add(i)
        if any("representative" in xs[i] for i in chosen):
            for i,s in enumerate(xs):
                if _has(s,("representative means","representatives shall include","representative” of","representative of a person")): out.add(i)
    return sorted(out)

